-- The off-chain marketplace's log. `hashed_signature` is keccak256 of the
-- trade signature (shop.trades.hashed_signature), `caller` the
-- transaction's msg sender (for a cancellation, whose signature it cancels),
-- `new_index` the raised signer or contract signature index, `signer` and
-- `assets` the Traded event's trade (its sent/received arrays, read as a unit).
CREATE TABLE shop.trade_event (
    network text NOT NULL,
    block_number bigint NOT NULL,
    log_index integer NOT NULL,
    block_time bigint NOT NULL,
    marketplace_address varchar(42) NOT NULL,
    kind text NOT NULL,
    caller varchar(42) NOT NULL,
    hashed_signature text,
    new_index numeric(78,0),
    signer varchar(42),
    assets jsonb,
    tx_hash text NOT NULL,
    PRIMARY KEY (network, block_number, log_index),
    CONSTRAINT trade_event_network_known CHECK (network IN ('ethereum', 'matic')),
    CONSTRAINT trade_event_kind_known CHECK (kind IN ('traded', 'signature_cancelled', 'signer_index_increased', 'contract_index_increased')),
    CONSTRAINT trade_event_signature_kinds CHECK ((kind IN ('traded', 'signature_cancelled')) = (hashed_signature IS NOT NULL)),
    CONSTRAINT trade_event_index_kinds CHECK ((kind IN ('signer_index_increased', 'contract_index_increased')) = (new_index IS NOT NULL)),
    CONSTRAINT trade_event_lowercase CHECK (marketplace_address = lower(marketplace_address) AND caller = lower(caller))
);

-- A trade's executions and cancellations: WHERE hashed_signature = ANY($1).
CREATE INDEX trade_event_signature_idx ON shop.trade_event (hashed_signature, kind) WHERE hashed_signature IS NOT NULL;
-- The current signer / contract index of a marketplace: the latest row of
-- (network, marketplace_address, kind, caller) by block.
CREATE INDEX trade_event_index_idx ON shop.trade_event (network, marketplace_address, kind, caller, block_number DESC, log_index DESC) WHERE new_index IS NOT NULL;

-- The chain's verdict on each stored trade, folded from trade_event: `sold`
-- once its Traded executions reach checks.uses, `cancelled` when its signer
-- cancelled the signature (v1/v2 by keccak256 of the signature, v3 by the
-- EIP-712 digest, computed here from the row) or a signer or contract
-- signature index moved away from the one it was signed with, else `open`.
-- Expiry and local cancellations stay read-time rules. Derived: a rebuild
-- refolds every trade; a trade row deleted takes its verdict with it.
CREATE TABLE shop.trade_chain_state (
    trade_id uuid PRIMARY KEY REFERENCES shop.trades(id) ON DELETE CASCADE,
    network text NOT NULL,
    digest text,
    executions integer NOT NULL DEFAULT 0,
    status text NOT NULL,
    executed_at bigint,
    folded_block bigint NOT NULL,
    CONSTRAINT trade_chain_state_status_known CHECK (status IN ('open', 'sold', 'cancelled')),
    CONSTRAINT trade_chain_state_executions_nonneg CHECK (executions >= 0)
);

-- A v3 cancellation names the digest: WHERE digest = ANY($1) (the fold's touched set).
CREATE INDEX trade_chain_state_digest_idx ON shop.trade_chain_state (digest) WHERE digest IS NOT NULL;

-- The Rentals contract's log on Ethereum (the `rentals` chain index,
-- src/shop/rentals/index.rs), the
-- source of every rentals listing's status: a rent (`rented`: the lessor in
-- `signer`, the tenant, the operator, the days and price, and the listing
-- signature it consumed), a claim (`claimed`), and the three nonce bumps
-- (`asset_index_updated` with the signer and the asset, `signer_index_updated`
-- with the signer, `contract_index_updated`), each with the raised index.
-- Keyed by the chain's position, appended with the cursor advance; a reorg
-- rewind deletes past the rewind block and the next fold rebuilds.
CREATE TABLE shop.rental_event (
    network text NOT NULL,
    block_number bigint NOT NULL,
    log_index integer NOT NULL,
    block_time bigint NOT NULL,
    rentals_address varchar(42) NOT NULL,
    kind text NOT NULL,
    contract_address varchar(42),
    token_id numeric(78,0),
    signer varchar(42),
    tenant varchar(42),
    operator varchar(42),
    rental_days integer,
    price_per_day numeric(78,0),
    is_extension boolean,
    sender varchar(42),
    signature text,
    new_index numeric(78,0),
    tx_hash text NOT NULL,
    PRIMARY KEY (network, block_number, log_index),
    CONSTRAINT rental_event_network_known CHECK (network IN ('ethereum')),
    CONSTRAINT rental_event_kind_known CHECK (kind IN ('rented', 'claimed', 'asset_index_updated', 'signer_index_updated', 'contract_index_updated')),
    CONSTRAINT rental_event_asset_kinds CHECK ((kind IN ('rented', 'claimed', 'asset_index_updated')) = (contract_address IS NOT NULL AND token_id IS NOT NULL)),
    CONSTRAINT rental_event_rented_fields CHECK ((kind = 'rented') = (signature IS NOT NULL AND tenant IS NOT NULL AND rental_days IS NOT NULL AND price_per_day IS NOT NULL)),
    CONSTRAINT rental_event_index_kinds CHECK ((kind IN ('asset_index_updated', 'signer_index_updated', 'contract_index_updated')) = (new_index IS NOT NULL)),
    CONSTRAINT rental_event_lowercase CHECK (rentals_address = lower(rentals_address) AND (contract_address IS NULL OR contract_address = lower(contract_address)) AND (signature IS NULL OR signature = lower(signature)))
);

-- The fold's per-asset legs: a listing's rent and claim, and the lessor's
-- asset bump (WHERE rentals_address = $2 AND contract_address, token_id = ...).
CREATE INDEX rental_event_asset_idx ON shop.rental_event (rentals_address, contract_address, token_id, block_number, log_index) WHERE contract_address IS NOT NULL;
-- The rent that consumed a listing: WHERE kind = 'rented' AND signature = lower(r.signature).
CREATE INDEX rental_event_signature_idx ON shop.rental_event (signature) WHERE kind = 'rented';
-- The lessor's signer index: WHERE kind = 'signer_index_updated' AND signer = l.lessor.
CREATE INDEX rental_event_signer_idx ON shop.rental_event (signer, new_index) WHERE kind = 'signer_index_updated';

-- The MANA transactions wallets reported after sending them (SHOP.md slice
-- 3, src/shop/mana/{executions,tracker}.rs), tracked to a verdict by the
-- `executions-track` job: the
-- expectation columns come from the record the report names (the trade, the
-- order, the rental listing, the label), never from the body; `settlement`
-- is what the receipt proved and the final comparison; `(chain_id, tx_hash)`
-- is the idempotency key of a report. `submitted` -> `mined` -> `settled` |
-- `mismatch`; `reverted` and `dropped` are terminal too.
CREATE TABLE shop.executions (
    id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
    chain_id bigint NOT NULL,
    tx_hash text NOT NULL,
    kind text NOT NULL,
    actor varchar(42) NOT NULL,
    venue varchar(42) NOT NULL,
    contract_address varchar(42),
    token_id numeric(78,0),
    reference text,
    expected_price numeric(78,0),
    mana_token varchar(42),
    expected_seller varchar(42),
    expected_owner varchar(42),
    status text NOT NULL DEFAULT 'submitted',
    block_number bigint,
    confirmed_by text,
    settlement jsonb,
    attempts integer NOT NULL DEFAULT 0,
    last_error text,
    next_check_at timestamp without time zone NOT NULL,
    created_at timestamp without time zone NOT NULL,
    updated_at timestamp without time zone NOT NULL,
    UNIQUE (chain_id, tx_hash),
    CONSTRAINT executions_kind_known CHECK (kind IN ('accept_trade', 'execute_order', 'accept_rental', 'register_name', 'transfer', 'cancel_trade', 'cancel_order', 'claim_rental', 'cancel_rental', 'approve_mana')),
    CONSTRAINT executions_status_known CHECK (status IN ('submitted', 'mined', 'reverted', 'settled', 'mismatch', 'dropped')),
    CONSTRAINT executions_confirmed_by_known CHECK (confirmed_by IS NULL OR confirmed_by IN ('receipt', 'index', 'finality')),
    CONSTRAINT executions_tx_hash_shape CHECK (tx_hash ~ '^0x[0-9a-f]{64}$'),
    CONSTRAINT executions_price_nonneg CHECK (expected_price IS NULL OR expected_price >= 0),
    CONSTRAINT executions_lowercase CHECK (actor = lower(actor) AND venue = lower(venue) AND (contract_address IS NULL OR contract_address = lower(contract_address)))
);

-- The tracker's due set: WHERE status IN ('submitted', 'mined') AND next_check_at <= $now ORDER BY next_check_at.
CREATE INDEX executions_due_idx ON shop.executions (next_check_at) WHERE status IN ('submitted', 'mined');
-- A wallet's own executions: WHERE actor = $1 ORDER BY created_at DESC.
CREATE INDEX executions_actor_idx ON shop.executions (actor, created_at DESC);

-- Item co-ownership neighbours (/v3/catalog/suggested), derived from the
-- nft fold by the `item-neighbours` job: for every item held with others,
-- its top neighbours by a cosine over the wallets holding both, shrunk by
-- the co-owner count. Rebuilt whole in one transaction per run; the meta
-- row names the fold it was built from.
CREATE TABLE shop.item_neighbors (
    network text NOT NULL,
    contract_address varchar(42) NOT NULL,
    item_id numeric(78,0) NOT NULL,
    neighbor_network text NOT NULL,
    neighbor_contract_address varchar(42) NOT NULL,
    neighbor_item_id numeric(78,0) NOT NULL,
    sim real NOT NULL,
    support integer NOT NULL,
    rank smallint NOT NULL,
    PRIMARY KEY (network, contract_address, item_id, neighbor_network, neighbor_contract_address, neighbor_item_id),
    CONSTRAINT item_neighbors_sim_range CHECK (sim > 0 AND sim <= 1),
    CONSTRAINT item_neighbors_rank_positive CHECK (rank >= 1)
);

CREATE TABLE shop.item_neighbors_meta (
    id integer PRIMARY KEY CHECK (id = 1),
    built_at timestamp without time zone NOT NULL,
    algorithm text NOT NULL,
    wallets integer NOT NULL,
    items integer NOT NULL,
    rows_written integer NOT NULL,
    source_folded_block_matic bigint,
    source_folded_block_ethereum bigint
);

-- Creator-signed coupons (the old 0013_coupons.sql under marketplace, local
-- authority behind DATA_WRITES_ENABLED) and their on-chain state as the
-- `coupon-state-refresh` job last read it from the CouponManager.
CREATE TABLE shop.coupons (
    id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
    network text NOT NULL,
    chain_id integer NOT NULL,
    signer varchar(42) NOT NULL,
    signature text NOT NULL UNIQUE,
    hashed_signature text NOT NULL UNIQUE,
    state_key text NOT NULL UNIQUE,
    coupon_manager varchar(42) NOT NULL,
    coupon_address varchar(42) NOT NULL,
    checks jsonb NOT NULL,
    discount_type smallint NOT NULL,
    discount_ppm integer NOT NULL,
    root text NOT NULL,
    collections text[] NOT NULL,
    effective_since timestamp(3) without time zone NOT NULL,
    expires_at timestamp(3) without time zone NOT NULL,
    created_at timestamp(3) without time zone NOT NULL DEFAULT timezone('UTC', now())::timestamp(3),
    CONSTRAINT coupons_signer_lowercase CHECK (signer = lower(signer)),
    CONSTRAINT coupons_discount_ppm_within_bounds CHECK (discount_ppm >= 50000 AND discount_ppm <= 700000),
    CONSTRAINT coupons_effective_before_expiry CHECK (effective_since < expires_at)
);

-- GET /v1/coupons?signer=: WHERE signer = $1 ORDER BY created_at DESC LIMIT OFFSET.
CREATE INDEX coupons_signer_created_idx ON shop.coupons (signer, created_at DESC);
-- The refresh job's due set: WHERE expires_at > $now AND effective_since <= $now + 1 day.
CREATE INDEX coupons_expires_idx ON shop.coupons (expires_at);

CREATE TABLE shop.coupon_state (
    coupon_id uuid PRIMARY KEY REFERENCES shop.coupons(id) ON DELETE CASCADE,
    uses integer NOT NULL DEFAULT 0,
    cancelled boolean NOT NULL DEFAULT false,
    revoked boolean NOT NULL DEFAULT false,
    checked_at timestamp(3) without time zone NOT NULL DEFAULT timezone('UTC', now())::timestamp(3),
    CONSTRAINT coupon_state_uses_nonneg CHECK (uses >= 0)
);

-- The market federation's signed-action log (src/marketplace/federation.rs,
-- the old market_{bids,orders,trades}_local, market_cancellations and
-- market_bid_acceptances folded into `kind`): each wallet-signed envelope of
-- the DecentralandMarket domain once, keyed by its digest, numbered by one
-- identity `seq` the changes feed pages by. Local authority; no route but
-- /v1/federation/* and /federation/market/* reads it. `signed_at`,
-- `expires_at` and `taken_at` are the envelope's signed unix seconds.
CREATE TABLE shop.fed_actions (
    signature_hash text PRIMARY KEY,
    seq bigint GENERATED ALWAYS AS IDENTITY,
    kind text NOT NULL,
    signer varchar(42) NOT NULL,
    item_id text,
    target_hash text,
    target_kind text,
    price numeric(78,0),
    expires_at bigint,
    fingerprint text,
    buyer text,
    tx_hash text,
    taken_at bigint,
    signed_at bigint NOT NULL,
    message_payload jsonb NOT NULL,
    received_at timestamp without time zone NOT NULL DEFAULT timezone('UTC', now()),
    CONSTRAINT fed_actions_seq_key UNIQUE (seq),
    CONSTRAINT fed_actions_kind_known CHECK (kind IN ('bid', 'order', 'trade', 'cancel', 'accept')),
    CONSTRAINT fed_actions_signer_lowercase CHECK (signer = lower(signer)),
    CONSTRAINT fed_actions_listing_shape CHECK ((kind IN ('bid', 'order')) = (item_id IS NOT NULL AND price IS NOT NULL AND expires_at IS NOT NULL)),
    CONSTRAINT fed_actions_target_shape CHECK ((kind IN ('trade', 'cancel', 'accept')) = (target_hash IS NOT NULL)),
    CONSTRAINT fed_actions_cancel_shape CHECK ((kind = 'cancel') = (target_kind IS NOT NULL) AND (target_kind IS NULL OR target_kind IN ('bid', 'order'))),
    CONSTRAINT fed_actions_trade_shape CHECK ((kind = 'trade') = (buyer IS NOT NULL AND tx_hash IS NOT NULL AND taken_at IS NOT NULL)),
    CONSTRAINT fed_actions_buyer_lowercase CHECK (buyer = lower(buyer)),
    CONSTRAINT fed_actions_price_nonneg CHECK (price >= 0)
);
-- The lists `WHERE kind = $1 ORDER BY seq DESC LIMIT 500`, the changes feed
-- `WHERE kind = $1 AND seq > $2 ORDER BY seq LIMIT $3`, the snapshot's
-- `max(seq)` and digests per kind.
CREATE INDEX fed_actions_kind_seq_idx ON shop.fed_actions (kind, seq);

-- The federation's replay store (crate::fed::check_and_record): a signer's
-- nonce is refused while recorded; kept signed_at + 360 s.
CREATE TABLE shop.fed_seen_nonces (
    signer text NOT NULL,
    nonce text NOT NULL,
    expires_at bigint NOT NULL,
    PRIMARY KEY (signer, nonce)
);
-- The `market-fed-nonce-sweep` job: DELETE ... WHERE expires_at < $1.
CREATE INDEX fed_seen_nonces_expires_idx ON shop.fed_seen_nonces (expires_at);

-- ── checkout: the settlement ledgers (src/shop/checkout; from `economy`) ────

-- Relayer-paid NFT purchases routed to the Landiler escrow. A row is claimed
-- by idempotency key BEFORE the broadcast; the reconciler settles it from
-- receipts. `price_wei` is the execution-time MANA charge; the two usd
-- columns keep a USD-pegged trade's signed amount and the oracle rate used.
CREATE TABLE shop.broker_purchases (
    id bigint PRIMARY KEY GENERATED ALWAYS AS IDENTITY,
    idempotency_key text,
    tx_hash text,
    forward_tx_hash text,
    collection varchar(42) NOT NULL,
    item_id text,
    token_id text,
    minted_token_id text,
    buyer_address varchar(42),
    escrow_address varchar(42) NOT NULL,
    price_wei numeric(78,0) NOT NULL,
    usd_amount_wei numeric(78,0),
    mana_usd_rate_wei numeric(78,0),
    trade_hashed_signature text,
    chain_id bigint NOT NULL,
    mode text NOT NULL,
    status text NOT NULL DEFAULT 'sent',
    created_at timestamp without time zone NOT NULL DEFAULT timezone('UTC', now()),
    updated_at timestamp without time zone NOT NULL DEFAULT timezone('UTC', now()),
    CONSTRAINT broker_purchases_status_known
        CHECK (status IN ('pending', 'sent', 'reverted', 'bought', 'forwarding', 'confirmed', 'error')),
    CONSTRAINT broker_purchases_mode_valid
        CHECK (mode IN ('primary', 'secondary', 'trade', 'name-mint', 'name-secondary')),
    CONSTRAINT broker_purchases_collection_lowercase CHECK (collection = lower(collection)),
    CONSTRAINT broker_purchases_price_nonneg CHECK (price_wei >= 0)
);

-- The claim: INSERT ... ON CONFLICT (idempotency_key) WHERE idempotency_key IS NOT NULL DO NOTHING.
CREATE UNIQUE INDEX broker_purchases_idempotency_key_uidx
    ON shop.broker_purchases (idempotency_key) WHERE idempotency_key IS NOT NULL;
-- A second logical purchase of a one-use signed trade is refused before any gas is spent.
CREATE UNIQUE INDEX broker_purchases_trade_sig_uidx
    ON shop.broker_purchases (trade_hashed_signature)
    WHERE trade_hashed_signature IS NOT NULL AND status NOT IN ('reverted', 'error');
-- The reconciler's bounded due set: WHERE status IN (...) ORDER BY id LIMIT 100.
CREATE INDEX broker_purchases_unsettled_idx
    ON shop.broker_purchases (id) WHERE status IN ('sent', 'bought', 'forwarding');

-- LandilerEscrow lifecycle calls (reclaim before unlock, release at/after).
CREATE TABLE shop.escrow_actions (
    id bigint PRIMARY KEY GENERATED ALWAYS AS IDENTITY,
    action text NOT NULL,
    collection varchar(42),
    token_id text,
    buyer varchar(42),
    escrow_address varchar(42),
    tx_hash text,
    idempotency_key text,
    status text NOT NULL DEFAULT 'sent',
    chain_id bigint,
    created_at timestamp without time zone NOT NULL DEFAULT timezone('UTC', now()),
    updated_at timestamp without time zone NOT NULL DEFAULT timezone('UTC', now()),
    CONSTRAINT escrow_actions_action_known CHECK (action IN ('reclaim', 'release')),
    CONSTRAINT escrow_actions_status_known CHECK (status IN ('pending', 'sent', 'confirmed', 'reverted', 'error'))
);

CREATE UNIQUE INDEX escrow_actions_idempotency_key_uidx
    ON shop.escrow_actions (idempotency_key) WHERE idempotency_key IS NOT NULL;
-- The reconciler's due set.
CREATE INDEX escrow_actions_unsettled_idx ON shop.escrow_actions (id) WHERE status = 'sent';

-- Relayer-custodied NAME transfers (the manage/release leg of the NAME lease).
CREATE TABLE shop.name_transfers (
    id bigint PRIMARY KEY GENERATED ALWAYS AS IDENTITY,
    idempotency_key text NOT NULL UNIQUE,
    registrar varchar(42) NOT NULL,
    token_id text NOT NULL,
    from_address varchar(42) NOT NULL,
    to_address varchar(42) NOT NULL,
    chain_id bigint NOT NULL,
    tx_hash text,
    status text NOT NULL DEFAULT 'pending',
    created_at timestamp without time zone NOT NULL DEFAULT timezone('UTC', now()),
    updated_at timestamp without time zone NOT NULL DEFAULT timezone('UTC', now()),
    CONSTRAINT name_transfers_status_known CHECK (status IN ('pending', 'sent', 'confirmed', 'reverted', 'error'))
);

-- The reconciler's due set.
CREATE INDEX name_transfers_unsettled_idx ON shop.name_transfers (id) WHERE status = 'sent';

-- The escrow lease overlay: while the escrow holds a bought NFT, the buyer may
-- use it. Written by the broker on confirmation; read by the lambdas' owned
-- items routes (UNION ALL over the readers) and the profile filter.
CREATE TABLE shop.usage_grants (
    id bigint PRIMARY KEY GENERATED ALWAYS AS IDENTITY,
    grantee_address varchar(42) NOT NULL,
    urn text NOT NULL,
    token_id text,
    collection varchar(42),
    category text NOT NULL,
    escrow_ref text,
    granted_at timestamp without time zone NOT NULL DEFAULT timezone('UTC', now()),
    unlock_at timestamp without time zone NOT NULL,
    status text NOT NULL DEFAULT 'active',
    CONSTRAINT usage_grants_grantee_lowercase CHECK (grantee_address = lower(grantee_address)),
    CONSTRAINT usage_grants_category_known CHECK (category IN ('wearable', 'emote')),
    CONSTRAINT usage_grants_status_known CHECK (status IN ('active', 'revoked', 'released'))
);

-- The overlay: WHERE grantee_address = $1 AND status = 'active' AND unlock_at > $now,
-- and the deploy validator's per-item probe (the same grantee prefix, its
-- `urn = ANY($2) OR urn LIKE ANY($3)` a filter on the rows: no btree on urn
-- serves an OR of a LIKE).
CREATE INDEX usage_grants_grantee_idx ON shop.usage_grants (grantee_address) WHERE status = 'active';
-- The broker's idempotent grant write (token_id NULL for a primary mint).
CREATE UNIQUE INDEX usage_grants_natural_key
    ON shop.usage_grants (escrow_ref, urn, token_id) NULLS NOT DISTINCT
    WHERE escrow_ref IS NOT NULL;

-- ═══ The shop-server fold (SHOP.md, "Backend work" 6; src/shop/{outfits,subscriptions,treasury}) ═══
--
-- Derived from shop-server@dc1a8be96's migrations (1751414400000_init-treasury-ledger,
-- 1751500800000_add-treasury-pending-refill, 1752192000000_init-item-notify-requests,
-- 1785456000000_create-outfits); the proceeds reconciliation snapshots
-- (1752278400000) are not carried (that flow pays resale sellers in credits).
-- Money is numeric(78,0) base units (USDC 6 decimals, MANA 18), never a float;
-- the shop-server millisecond timestamps stay bigint where the wire shape
-- exposes them (outfits, the ledger), the waitlist keeps UTC timestamps.

-- Curated shoppable wearable sets, authored by the allowlisted creators
-- (SHOP_OUTFIT_CREATORS). `id` is the client-generated v4 uuid (POST is
-- idempotent on it); items are (contractAddress, itemId) pairs, never trade
-- ids; the publish bar (a thumbnail, both gradient stops, 1..20 items) is the
-- handlers' `is_publishable`, declared here too.
CREATE TABLE shop.outfits (
    id text PRIMARY KEY,
    name text NOT NULL,
    thumbnail_hash text NOT NULL DEFAULT '',
    items jsonb NOT NULL,
    body_shape text NOT NULL,
    gradient_from text NOT NULL DEFAULT '',
    gradient_to text NOT NULL DEFAULT '',
    author_address varchar(42) NOT NULL,
    published boolean NOT NULL DEFAULT false,
    created_at bigint NOT NULL,
    updated_at bigint NOT NULL,
    CONSTRAINT outfits_id_uuid CHECK (id ~ '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'),
    CONSTRAINT outfits_name_length CHECK (char_length(name) BETWEEN 1 AND 60),
    CONSTRAINT outfits_thumbnail_sha256 CHECK (thumbnail_hash = '' OR thumbnail_hash ~ '^[0-9a-f]{64}$'),
    CONSTRAINT outfits_items_array CHECK (jsonb_typeof(items) = 'array' AND jsonb_array_length(items) <= 20),
    CONSTRAINT outfits_body_shape_known CHECK (body_shape IN ('male', 'female', 'unisex')),
    CONSTRAINT outfits_gradient_from_hex CHECK (gradient_from = '' OR gradient_from ~ '^#[0-9a-f]{6}$'),
    CONSTRAINT outfits_gradient_to_hex CHECK (gradient_to = '' OR gradient_to ~ '^#[0-9a-f]{6}$'),
    CONSTRAINT outfits_author_lowercase CHECK (author_address ~ '^0x[0-9a-f]{40}$'),
    CONSTRAINT outfits_publish_bar CHECK (
        NOT published OR (thumbnail_hash <> '' AND gradient_from <> '' AND gradient_to <> '' AND jsonb_array_length(items) >= 1)
    )
);

-- The public listing: WHERE published ORDER BY created_at DESC LIMIT 50 OFFSET n.
CREATE INDEX outfits_published_created_idx ON shop.outfits (created_at DESC) WHERE published;

-- Outfit thumbnails: `hash` is the sha256 hex of the bytes, the wire id
-- (`{hash}` of POST /v1/outfits/thumbnails, `thumbnail_hash` above); the
-- bytes live in the ONE blob store under `blob_cid` (`auth::hash_bytes_v1`),
-- which storage::gc names as a reference. Content-addressed and shared
-- between outfits, so an outfit's deletion never cascades into them.
CREATE TABLE shop.outfit_thumbnails (
    hash text PRIMARY KEY,
    blob_cid text NOT NULL,
    content_type text NOT NULL,
    size integer NOT NULL,
    author_address varchar(42) NOT NULL,
    created_at bigint NOT NULL,
    CONSTRAINT outfit_thumbnails_hash_sha256 CHECK (hash ~ '^[0-9a-f]{64}$'),
    CONSTRAINT outfit_thumbnails_type_known CHECK (content_type IN ('image/png', 'image/jpeg', 'image/webp')),
    CONSTRAINT outfit_thumbnails_size_bounds CHECK (size > 0 AND size <= 1048576),
    CONSTRAINT outfit_thumbnails_author_lowercase CHECK (author_address ~ '^0x[0-9a-f]{40}$')
);

-- "Notify me when available": one row per (wallet, contract, item), the
-- wallet the verified signer. pending -> notified (once, by the outbox
-- below) or unsubscribed (terminal); a re-subscribe resets a notified row to
-- pending. Addresses are stored lowercase (declared, not folded on read).
CREATE TABLE shop.item_notify_requests (
    id bigint PRIMARY KEY GENERATED ALWAYS AS IDENTITY,
    address varchar(42) NOT NULL,
    email text NOT NULL,
    contract_address varchar(42) NOT NULL,
    item_id text NOT NULL,
    chain_id integer NOT NULL,
    status text NOT NULL DEFAULT 'pending',
    created_at timestamp without time zone NOT NULL DEFAULT timezone('UTC', now()),
    updated_at timestamp without time zone NOT NULL DEFAULT timezone('UTC', now()),
    notified_at timestamp without time zone,
    CONSTRAINT item_notify_requests_addr_item_uniq UNIQUE (address, contract_address, item_id),
    CONSTRAINT item_notify_requests_address_lowercase CHECK (address ~ '^0x[0-9a-f]{40}$'),
    CONSTRAINT item_notify_requests_contract_lowercase CHECK (contract_address ~ '^0x[0-9a-f]{40}$'),
    CONSTRAINT item_notify_requests_item_id_length CHECK (char_length(item_id) BETWEEN 1 AND 78),
    CONSTRAINT item_notify_requests_email_length CHECK (char_length(email) BETWEEN 3 AND 254),
    CONSTRAINT item_notify_requests_chain_positive CHECK (chain_id >= 1),
    CONSTRAINT item_notify_requests_status_known CHECK (status IN ('pending', 'notified', 'unsubscribed'))
);

-- The fan-out's keyset page: WHERE contract_address = $1 AND item_id = $2
-- AND status = 'pending' AND id > $after ORDER BY id LIMIT 100; and the
-- availability watcher's distinct pending items.
CREATE INDEX item_notify_requests_pending_idx ON shop.item_notify_requests (contract_address, item_id, id) WHERE status = 'pending';

-- The delivery outbox of the waitlist (the SQS hop of shop-server as a
-- local transactional row): an item's on-sale transition inserts one row
-- per pending subscriber in the transaction that records the transition;
-- the `shop-notify-deliveries` job claims due rows under a lease, sends
-- the email outside any transaction, then flips the row to sent and the
-- request to notified in one statement. At most one pending row per
-- request (the partial unique), so a duplicate trigger enqueues nothing.
CREATE TABLE shop.item_notify_outbox (
    id bigint PRIMARY KEY GENERATED ALWAYS AS IDENTITY,
    request_id bigint NOT NULL REFERENCES shop.item_notify_requests (id) ON DELETE CASCADE,
    contract_address varchar(42) NOT NULL,
    item_id text NOT NULL,
    item_name text,
    trigger text NOT NULL,
    status text NOT NULL DEFAULT 'pending',
    attempts integer NOT NULL DEFAULT 0,
    next_attempt_at timestamp without time zone NOT NULL DEFAULT timezone('UTC', now()),
    last_error text,
    provider_message_id text,
    created_at timestamp without time zone NOT NULL DEFAULT timezone('UTC', now()),
    updated_at timestamp without time zone NOT NULL DEFAULT timezone('UTC', now()),
    sent_at timestamp without time zone,
    CONSTRAINT item_notify_outbox_status_known CHECK (status IN ('pending', 'sent', 'failed', 'skipped')),
    CONSTRAINT item_notify_outbox_attempts_nonneg CHECK (attempts >= 0)
);

-- One pending delivery per request (the enqueue's conflict target).
CREATE UNIQUE INDEX item_notify_outbox_pending_once ON shop.item_notify_outbox (request_id) WHERE status = 'pending';
-- The worker's due set: WHERE status = 'pending' AND next_attempt_at <= now ORDER BY next_attempt_at, id LIMIT 100 FOR UPDATE SKIP LOCKED.
CREATE INDEX item_notify_outbox_due_idx ON shop.item_notify_outbox (next_attempt_at, id) WHERE status = 'pending';

-- What the availability watcher last saw of an item somebody waits for:
-- `on_sale` is `shop.items` (available > 0 and a store minter and an
-- approved collection) at `observed_at`; NULL until first observed, so the
-- first observation is the baseline and only a later false -> true
-- transition notifies (upstream keyed on the ITEM_PUBLISHED event).
CREATE TABLE shop.item_availability_watch (
    contract_address varchar(42) NOT NULL,
    item_id text NOT NULL,
    on_sale boolean,
    observed_at timestamp without time zone NOT NULL,
    changed_at timestamp without time zone,
    PRIMARY KEY (contract_address, item_id),
    CONSTRAINT item_availability_watch_contract_lowercase CHECK (contract_address ~ '^0x[0-9a-f]{40}$')
);

-- The treasury ledger: append-only, every flow one row with signed deltas
-- from the treasury's point of view. usdc_deposit is a SALE (a card
-- receivable still at the processor), usdc_settlement is USDC that ARRIVED
-- on-chain, refill is USDC out / MANA into the CreditsManager, fee_retained
-- is MANA kept, withdrawal_recorded is a refund or chargeback for audit only
-- (never counted by the summary: no USDC left the chain). Entries with a
-- reference are idempotent on (type, reference).
CREATE TABLE shop.treasury_ledger (
    id uuid PRIMARY KEY,
    type text NOT NULL,
    usdc_delta numeric(78,0) NOT NULL DEFAULT 0,
    mana_delta numeric(78,0) NOT NULL DEFAULT 0,
    reference text,
    metadata jsonb,
    created_at bigint NOT NULL,
    CONSTRAINT treasury_ledger_type_known
        CHECK (type IN ('usdc_deposit', 'usdc_settlement', 'refill', 'fee_retained', 'withdrawal_recorded'))
);

-- The idempotent record (a replayed webhook or payout returns the existing row).
CREATE UNIQUE INDEX treasury_ledger_type_reference_uniq ON shop.treasury_ledger (type, reference) WHERE reference IS NOT NULL;
-- The status page's recent entries and the daily digest's 24 h window: ORDER BY created_at DESC LIMIT n.
CREATE INDEX treasury_ledger_created_idx ON shop.treasury_ledger (created_at DESC);
-- The refill rate breaker: COUNT(*) WHERE type = 'refill' AND created_at >= $window_start.
CREATE INDEX treasury_ledger_refill_window_idx ON shop.treasury_ledger (created_at) WHERE type = 'refill';

-- A refill intent, written before any money moves and advanced after each
-- confirmed leg: pending -> swap_sent (the swap signed, its hash and raw
-- bytes durable, then broadcast) -> swapped (receipt confirmed, the fill
-- read from its logs) -> transfer_sent (the CreditsManager transfer signed
-- and durable, then broadcast) -> transferred -> settled (ledger row
-- linked); aborted is the terminal of a swap that never confirmed. A crash
-- between a broadcast and its status write is recovered by the persisted
-- hash (the receipt decides), never by signing again.
CREATE TABLE shop.treasury_pending_refill (
    id uuid PRIMARY KEY,
    idempotency_key text NOT NULL UNIQUE,
    status text NOT NULL,
    usdc_to_spend numeric(78,0) NOT NULL,
    mana_to_acquire numeric(78,0) NOT NULL,
    swap_nonce bigint,
    swap_raw_tx bytea,
    swap_tx_hash text,
    usdc_spent numeric(78,0),
    mana_acquired numeric(78,0),
    oracle_price numeric(78,0),
    transfer_nonce bigint,
    transfer_raw_tx bytea,
    transfer_tx_hash text,
    ledger_entry_id uuid,
    abort_reason text,
    created_at bigint NOT NULL,
    updated_at bigint NOT NULL,
    CONSTRAINT treasury_pending_refill_status_known
        CHECK (status IN ('pending', 'swap_sent', 'swapped', 'transfer_sent', 'transferred', 'settled', 'aborted')),
    CONSTRAINT treasury_pending_refill_amounts_positive CHECK (usdc_to_spend > 0 AND mana_to_acquire > 0)
);

-- The recovery scan every tick: the oldest unresolved intent.
CREATE INDEX treasury_pending_refill_unresolved_idx ON shop.treasury_pending_refill (created_at)
    WHERE status IN ('pending', 'swap_sent', 'swapped', 'transfer_sent', 'transferred');

-- One row per drift check (`shop-treasury-drift` and the refill's breaker):
-- the ledger's expectation against the chain, in basis points of the
-- expectation; the status page reads the newest.
CREATE TABLE shop.treasury_drift_checks (
    id bigint PRIMARY KEY GENERATED ALWAYS AS IDENTITY,
    expected_treasury_usdc numeric(78,0) NOT NULL,
    actual_treasury_usdc numeric(78,0) NOT NULL,
    usdc_drift_bps bigint NOT NULL,
    expected_credits_manager_mana numeric(78,0) NOT NULL,
    actual_credits_manager_mana numeric(78,0) NOT NULL,
    mana_drift_bps bigint NOT NULL,
    usdc_receivable numeric(78,0) NOT NULL,
    healthy boolean NOT NULL,
    checked_at bigint NOT NULL
);

-- The newest check: ORDER BY checked_at DESC LIMIT 1.
CREATE INDEX treasury_drift_checks_checked_idx ON shop.treasury_drift_checks (checked_at DESC);

-- ── Slice 5: campaigns (local: the seasonal storefront) ────────────────────
--
-- The Shop owns the campaign as data (src/shop/campaigns): upstream read the
-- marketing CMS for the campaign entry and the Builder for the collections a
-- tag selects; v2's Builder keeps no collection tags and a CMS is not on
-- every node. One row per campaign, its window, its tags and the banner
-- content (the CMS fields, opaque); written by the operator behind
-- MARKET_ADMIN_TOKEN and DATA_WRITES_ENABLED.
CREATE TABLE shop.campaigns (
    id text PRIMARY KEY,
    name text NOT NULL,
    tab_name text,
    main_tag text NOT NULL,
    tags text[] NOT NULL DEFAULT '{}',
    starts_at timestamp without time zone,
    ends_at timestamp without time zone,
    enabled boolean NOT NULL DEFAULT false,
    banner jsonb NOT NULL DEFAULT '{}'::jsonb,
    updated_by text NOT NULL,
    updated_at timestamp without time zone NOT NULL DEFAULT timezone('UTC', now()),
    CONSTRAINT campaigns_id_slug CHECK (id ~ '^[a-z0-9][a-z0-9-]{0,63}$'),
    CONSTRAINT campaigns_window CHECK (starts_at IS NULL OR ends_at IS NULL OR starts_at < ends_at)
);

-- The approved collections a campaign tag selects (the Builder's
-- GET /v1/addresses?tag= answer): PK = the tag's set, replaced whole by
-- PUT /admin/campaigns/{id}/collections. No FK to collections: a mirror row
-- may be re-walked; the write checks approval at the time of the write.
CREATE TABLE shop.campaign_collections (
    tag text NOT NULL,
    network text NOT NULL,
    contract_address varchar(42) NOT NULL,
    added_by text NOT NULL,
    created_at timestamp without time zone NOT NULL DEFAULT timezone('UTC', now()),
    PRIMARY KEY (tag, network, contract_address),
    CONSTRAINT campaign_collections_network_known CHECK (network IN ('ethereum', 'matic')),
    CONSTRAINT campaign_collections_contract_lowercase CHECK (contract_address = lower(contract_address))
);

CREATE TABLE shop.mana_transfer (
    network text NOT NULL CHECK (network IN ('ethereum', 'matic')),
    block_number bigint NOT NULL CHECK (block_number >= 0),
    log_index integer NOT NULL CHECK (log_index >= 0),
    transaction_hash text NOT NULL CHECK (transaction_hash ~ '^0x[0-9a-f]{64}$'),
    sender text NOT NULL CHECK (sender ~ '^0x[0-9a-f]{40}$'),
    recipient text NOT NULL CHECK (recipient ~ '^0x[0-9a-f]{40}$'),
    amount numeric(78,0) NOT NULL CHECK (amount >= 0 AND amount <= 115792089237316195423570985008687907853269984665640564039457584007913129639935),
    timestamp bigint NOT NULL CHECK (timestamp >= 0),
    PRIMARY KEY (network, block_number, log_index)
);
CREATE INDEX mana_transfer_sender ON shop.mana_transfer (network, sender, block_number DESC, log_index DESC);
CREATE INDEX mana_transfer_recipient ON shop.mana_transfer (network, recipient, block_number DESC, log_index DESC);
